<script setup lang="ts">
import {computed,onMounted,ref} from 'vue';
import {useProject} from './store';
import {settings} from './site-settings';
import {websiteProject} from './websites';
import {task} from './tasks';
import type {Catalog,Snapshot,Page} from './model';
import WebsitePreview from './WebsitePreview.vue';
import SafeContent from './SafeContent.vue';
import WebsiteLabels from './WebsiteLabels.vue';
import {download} from './api';
import {translationSheet,importTranslation} from './translation-sheet';
const props=defineProps<{catalog:Catalog}>(),emit=defineEmits<{next:[]}>(),store=useProject(),busy=ref(false),error=ref(''),translationLocale=ref('');
const project=computed(()=>websiteProject(store.project)),site=computed(()=>settings(store.project));
const allowed=computed(()=>[...new Set(project.value.company.markets.flatMap(id=>props.catalog.marketLanguages[id]||[]))]);
const chosen=computed({get:()=>site.value.publishLanguages??store.project.languages.filter(id=>allowed.value.includes(id)),set:(value:string[])=>{site.value.publishLanguages=value;store.project.languages=[...new Set([...store.project.languages,...value])];store.changed();}});
const defaultLanguage=computed({get:()=>chosen.value[0]||'',set:(value:string)=>{chosen.value=[value,...chosen.value.filter(id=>id!==value)];}});
const translations=computed(()=>chosen.value.filter(l=>l!==store.project.sourceLanguage));
const locale=computed({get:()=>translations.value.includes(translationLocale.value)?translationLocale.value:translations.value[0]||'',set:(value:string)=>{translationLocale.value=value;}});
const currentTheme=computed(()=>props.catalog.themes.find(t=>t.id===store.project.theme));
const sourceChoices=computed(()=>Object.entries({...props.catalog.languageNames,[store.project.sourceLanguage]:props.catalog.languageNames[store.project.sourceLanguage]||store.project.sourceLanguage}));
function name(id:string){const label=props.catalog.languageNames[id]||id;let native=id;try{native=new Intl.DisplayNames([id],{type:'language'}).of(id)||id;}catch{}return native===label?label:label+' · '+native;}
function ready(id:string){return id===store.project.sourceLanguage||store.project.pages.every(p=>p.detailDeleted||p.content[id]?.title&&(!(p.content[store.project.sourceLanguage]?.html.trim())||p.content[id]?.html.trim()));}
async function save(){try{error.value='';await store.flush();}catch(e){error.value=e instanceof Error?e.message:String(e);}}
async function translate(){if(busy.value||!translations.value.some(l=>!ready(l))||!store.project.pages.length)return;busy.value=true;error.value='';try{await store.flush();store.accept(await task<Snapshot>('/api/v1/translations',store.revision));}catch(e){error.value=e instanceof Error?e.message:String(e);}finally{busy.value=false;}}
async function saveLanguages(){await save();if(!error.value)await translate();}
function sourceChanged(){if(!store.project.languages.includes(store.project.sourceLanguage))store.project.languages.push(store.project.sourceLanguage);store.changed();}
function text(p:Page){return p.content[locale.value]||{title:'',html:'',menuTitle:''};}
function update(p:Page,key:'title'|'html'|'menuTitle',value:string){p.content[locale.value]={...text(p),[key]:value};store.changed();}
async function exportSite(){try{error.value='';await store.flush();await download('/api/v1/website-export',store.revision,'website.zip');}catch(e){error.value=String(e);}}
async function exportSheet(){const url=URL.createObjectURL(new Blob([await translationSheet(store.project,locale.value)],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download='translation-'+locale.value+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
async function importSheet(event:Event){const input=event.target as HTMLInputElement,file=input.files?.[0];if(!file)return;const language=locale.value,revision=store.revision,snapshot=JSON.stringify(store.project);try{error.value='';if(file.size>3000000)throw Error('翻译表超过 3 MB');const csv=await file.text();if(revision!==store.revision||snapshot!==JSON.stringify(store.project)||language!==locale.value)throw Error('内容已变化，请重新导入');const imported=await importTranslation(store.project,language,csv);if(snapshot!==JSON.stringify(store.project))throw Error('内容已变化，请重新导入');store.project=imported;store.changed();await store.flush();}catch(e){error.value=e instanceof Error?e.message:String(e);}finally{input.value='';}}
onMounted(()=>{void translate();});
</script>
<template><div class="stack website-language-page">
 <section class="card sw-card"><header class="between"><div class="sw-heading-line"><h2>选择发布语言</h2><p class="small muted">仅从当前目标市场的语言中选择；未选择的语言不发布。</p></div><RouterLink class="button" to="/plan?tab=markets">修改目标市场</RouterLink></header><form @submit.prevent="saveLanguages"><div class="sw-language-options"><label v-for="id in allowed" :key="id" class="check"><input v-model="chosen" type="checkbox" :value="id">{{catalog.languageNames[id]||id}}</label><p v-if="!allowed.length">尚未选择目标市场。</p></div><div class="card-actions"><button class="primary">保存发布语言</button></div></form></section>
 <section class="card"><div class="between"><div><div class="sw-heading-line"><h2>自动翻译</h2><span class="tag">{{busy?'自动翻译中':'自动保存'}}</span></div><p>语言已根据目标市场配置：{{project.company.markets.map(id=>catalog.markets.find(m=>m.id===id)?.zh||id).join(' · ')||'尚未选择市场'}}</p></div><RouterLink class="button" to="/plan?tab=markets">修改目标市场</RouterLink></div><p>进入本页自动生成并保存，原文变化后自动更新。可直接预览或进入下一步，文字调整为选用功能。</p><p v-if="error" role="alert" class="error">{{error}} <button :disabled="busy" @click="translate">重试翻译</button></p><div class="language-list"><div v-for="id in chosen" :key="id" class="between"><span><strong>{{name(id)}}</strong> <span class="tag">{{id===store.project.sourceLanguage?'原文':ready(id)?'已保存':busy?'自动补全中':'等待自动翻译'}}</span>{{id===defaultLanguage?' · 默认':''}}</span></div></div><details><summary>语言设置（选用）</summary><form @submit.prevent="saveLanguages"><div class="grid2"><div><label for="source-language">原文语言</label><select id="source-language" v-model="store.project.sourceLanguage" @change="sourceChanged"><option v-for="[id,label] in sourceChoices" :key="id" :value="id">{{label}}</option></select></div><div><label for="default-language">默认显示语言</label><select id="default-language" v-model="defaultLanguage"><option v-for="id in chosen" :key="id" :value="id">{{name(id)}}</option></select></div></div><WebsiteLabels :locale="store.project.sourceLanguage"/><div class="card-actions"><button>保存设置</button></div></form></details></section>
 <details v-if="locale" class="card translation-editor"><summary>调整译文（选用）</summary><div class="language-tabs" role="tablist" aria-label="翻译语言"><button v-for="id in translations" :key="id" role="tab" :aria-selected="locale===id" :class="{selected:locale===id}" @click="locale=id">{{name(id)}}</button></div><div role="tabpanel"><p class="small muted">修改后点击下一步或切换语言会自动保存。</p><form @submit.prevent="save"><fieldset><legend>网站菜单</legend><template v-for="p in store.project.pages.filter(p=>!p.ownerPageId)" :key="p.id"><label :for="'tr-menu-'+p.id">{{p.title}}</label><input :id="'tr-menu-'+p.id" :value="text(p).menuTitle" :lang="locale" @input="update(p,'menuTitle',($event.target as HTMLInputElement).value)"></template></fieldset><div v-for="p in store.project.pages.filter(p=>!p.detailDeleted&&p.content[store.project.sourceLanguage]?.html.trim())" :key="p.id" class="editor-row"><h3>{{p.title}}</h3><div class="grid2"><div><p class="small muted">原文</p><SafeContent :html="p.content[store.project.sourceLanguage]?.html||''"/></div><div :lang="locale"><label :for="'tr-title-'+p.id">译文标题</label><input :id="'tr-title-'+p.id" :value="text(p).title" @input="update(p,'title',($event.target as HTMLInputElement).value)"><label :for="'tr-body-'+p.id">译文内容</label><SafeContent :id="'tr-body-'+p.id" class="translation-copy" contenteditable="true" role="textbox" aria-label="译文内容" aria-multiline="true" :html="text(p).html" @blur="update(p,'html',($event.target as HTMLElement).innerHTML)"/></div></div></div><WebsiteLabels :locale="locale"/><div class="card-actions"><button>保存修改</button></div></form><details><summary>导入与导出（选用）</summary><div class="card-actions"><button @click="exportSite">下载多语言网站</button><button @click="exportSheet">下载翻译表</button><label class="file-button">导入翻译表<input type="file" accept=".csv" @change="importSheet"></label></div></details></div></details>
 <details v-if="currentTheme" class="card language-preview-toggle"><summary>查看语言预览</summary><WebsitePreview :project="project" :theme="currentTheme"/></details>
 <div class="card-actions"><button class="primary" @click="save().then(()=>{if(!error)emit('next')})">下一步：通讯设置</button></div>
</div></template>
